// Versor Dragging — Geo, route: ref
// Source: versor-dragging
//
// Self-contained: every local import is inlined below. Requires only d3, geojson, react, topojson-client, topojson-specification, us-atlas, versor, world-atlas.
// versor ships no types — keep untyped-modules.d.ts beside this file.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

/// <reference path="./untyped-modules.d.ts" />

import { feature, mesh } from 'topojson-client';
import countries110m from 'world-atlas/countries-110m.json';
import statesUs from 'us-atlas/states-10m.json';
import type { GeometryCollection, Topology } from 'topojson-specification';
import type { Feature, FeatureCollection, Geometry, MultiLineString } from 'geojson';
import { useEffect, useMemo, useRef } from 'react';
import * as d3 from 'd3';
import versor from 'versor';

// ---- inlined from geo ----
// The atlases ship untyped JSON. One cast per topology at this boundary keeps every
// consumer strict, and converting here means each chart does not re-derive the same
// geometry at module load.

type Named = { name: string };
type NamedFeature = Feature<Geometry, Named>;

const world = countries110m as unknown as Topology<{
  countries: GeometryCollection<Named>;
  land: GeometryCollection;
}>;

const us = statesUs as unknown as Topology<{
  states: GeometryCollection<Named>;
  nation: GeometryCollection;
}>;

const worldCountries = feature(
  world,
  world.objects.countries
) as FeatureCollection<Geometry, Named>;

const worldLand = feature(world, world.objects.land) as FeatureCollection<Geometry>;

/** Shared borders only, so neighbouring outlines are stroked once instead of twice. */
const worldBorders = mesh(
  world,
  world.objects.countries,
  (a, b) => a !== b
) as MultiLineString;

const usNation = feature(us, us.objects.nation) as FeatureCollection<Geometry>;

const usStateBorders = mesh(
  us,
  us.objects.states,
  (a, b) => a !== b
) as MultiLineString;

/**
 * The 50 states plus DC. geoAlbersUsa cannot project FIPS ids of 60 and above
 * (territories) and returns null for them, which becomes a NaN centroid downstream.
 * Use this rather than the raw collection for anything Albers-projected.
 */
const usStates: NamedFeature[] = (
  feature(us, us.objects.states) as FeatureCollection<Geometry, Named>
).features.filter((d) => Number(d.id) < 60);

const usStatesCollection: FeatureCollection<Geometry, Named> = {
  type: 'FeatureCollection',
  features: usStates
};

/**
 * FNV-1a over an id, run through the murmur3 finalizer. Two-character FIPS ids barely
 * differ, and without the finalizer they map to a near-constant. Returns [0, 1).
 * Charts use it to synthesize per-region values deterministically instead of fetching.
 */
function hashUnit(id: string, salt = 0): number {
  let h = 2166136261 ^ salt;
  for (let i = 0; i < id.length; i++) {
    h = Math.imul(h ^ id.charCodeAt(i), 16777619);
  }
  h ^= h >>> 16;
  h = Math.imul(h, 2246822507);
  h ^= h >>> 13;
  return (h >>> 0) / 4294967296;
}

const MARGIN = 10;

const sphere: d3.GeoSphere = { type: 'Sphere' };
const graticule = d3.geoGraticule10();

/** Atlantic-facing start, so the first paint shows both hemispheres' coastlines. */
const INITIAL_ROTATE: [number, number, number] = [20, -20, 0];

type Cartesian = [number, number, number];
type Quaternion = [number, number, number, number];

export default function VersorDragging({ width }: { width: number }) {
  const svgRef = useRef<SVGSVGElement | null>(null);
  const height = Math.min(Math.round(width * 0.7), 520);

  const projection = useMemo(
    () =>
      d3
        .geoOrthographic()
        .precision(0.2)
        .rotate(INITIAL_ROTATE)
        .fitSize(
          [Math.max(width - MARGIN * 2, 0), Math.max(height - MARGIN * 2, 0)],
          sphere
        )
        .translate([width / 2, height / 2]),
    [width, height]
  );

  useEffect(() => {
    const node = svgRef.current;
    if (!node || width === 0) return;

    const svg = d3.select(node);
    svg.selectAll('*').remove();

    const path = d3.geoPath(projection);

    const ocean = svg
      .append('path')
      .attr('fill', 'var(--panel)')
      .attr('stroke', 'var(--muted)')
      .attr('stroke-width', 1);
    const grid = svg
      .append('path')
      .attr('fill', 'none')
      .attr('stroke', 'var(--line)')
      .attr('stroke-width', 0.6);
    const land = svg.append('path').attr('fill', 'var(--accent)').attr('fill-opacity', 0.35);
    const borders = svg
      .append('path')
      .attr('fill', 'none')
      .attr('stroke', 'var(--accent)')
      .attr('stroke-width', 0.5)
      .attr('stroke-opacity', 0.7)
      .attr('stroke-linejoin', 'round');

    svg
      .append('text')
      .attr('x', MARGIN)
      .attr('y', height - MARGIN)
      .attr('fill', 'var(--muted)')
      .attr('font-size', 12)
      .text('Drag the globe to rotate it.');

    function render() {
      ocean.attr('d', path(sphere) ?? '');
      grid.attr('d', path(graticule) ?? '');
      land.attr('d', path(worldLand) ?? '');
      borders.attr('d', path(worldBorders) ?? '');
    }
    render();

    // Versor dragging: convert the grabbed screen point to a unit vector, and on every move
    // compose the rotation that carries that original vector onto the current one. Rotating
    // by Euler angles instead would twist the globe as the pointer leaves the equator.
    let v0: Cartesian | null = null;
    let q0: Quaternion | null = null;
    let r0: [number, number, number] = INITIAL_ROTATE;

    function dragstarted(event: { x: number; y: number }) {
      const spherical = projection.invert?.([event.x, event.y]);
      if (!spherical) return;
      v0 = versor.cartesian(spherical);
      r0 = projection.rotate();
      q0 = versor(r0);
    }

    function dragged(event: { x: number; y: number }) {
      if (!v0 || !q0) return;
      const spherical = projection.rotate(r0).invert?.([event.x, event.y]);
      if (!spherical) return;
      const delta = versor.delta(v0, versor.cartesian(spherical));
      projection.rotate(versor.rotation(versor.multiply(q0, delta)));
      render();
      // Near the antipode of the grab point the delta is unstable, so re-anchor there.
      if (delta[0] < 0.7) dragstarted(event);
    }

    svg.call(
      d3
        .drag<SVGSVGElement, unknown>()
        .on('start', dragstarted)
        .on('drag', dragged)
    );

    return () => {
      svg.on('.drag', null);
      svg.selectAll('*').remove();
    };
  }, [width, height, projection]);

  if (width === 0) return null;

  return (
    <svg
      ref={svgRef}
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      style={{ cursor: 'grab', touchAction: 'none' }}
      role="img"
      aria-label="Orthographic globe of world land and coastlines, draggable to rotate freely"
    />
  );
}
